// ═══════════════════════════════════════════════════════════════════════════
//  COLE A SUA LISTA AQUI DENTRO DOS COLCHETES.
//
//  Aceita os nomes de campo mais comuns (nome/telefone/email, ou
//  full_name/phone/email). O que importa é ter TELEFONE — é por ele que o QS
//  descobre se a pessoa já está na base.
//
//  Dica: se a sua lista está no Excel/Sheets, peça a alguém (ou a mim) pra
//  transformar em JSON, ou troque este nó por um nó de Google Sheets ligado
//  direto no "Enviar para o QS".
// ═══════════════════════════════════════════════════════════════════════════
const LISTA = [
  { nome: "Maria Exemplo", telefone: "62 99999-0001", email: "maria@exemplo.com", fonte: "Lista resgate agosto" },
  { nome: "João Exemplo",  telefone: "5562999990002",                              fonte: "Lista resgate agosto" },
];
// ═══════════════════════════════════════════════════════════════════════════

function telefone(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return null;
  d = d.replace(/^0+/, '');
  if (!d.startsWith('55')) d = '55' + d;
  return (d.length === 12 || d.length === 13) ? d : null;
}

const pega = (o, ...chaves) => {
  for (const k of chaves) {
    const v = o[k];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
};

// Mandamos TODOS, inclusive os que parecem incompletos: o QS recusa com um
// motivo claro e o resumo no fim conta quantos e por quê. Descartar aqui, em
// silêncio, esconderia linha ruim na planilha — e você acharia que subiu tudo.
return LISTA.map((linha) => ({ json: {
  full_name:    [pega(linha, 'full_name', 'nome', 'name', 'Nome', 'cliente'),
                 pega(linha, 'last_name', 'sobrenome', 'Sobrenome')].filter(Boolean).join(' ') || null,
  phone:        telefone(pega(linha, 'phone', 'telefone', 'whatsapp', 'celular', 'Telefone', 'WhatsApp')),
  email:        pega(linha, 'email', 'e-mail', 'Email', 'E-mail'),
  segment:      pega(linha, 'segment', 'fonte', 'origem', 'Fonte') ?? 'Resgate',
  source:       pega(linha, 'source') ?? 'resgate',
  // Temperatura, se a sua lista tiver ("Quente" / "Morno" / "Frio").
  lead_score:   pega(linha, 'lead_score', 'LeadScoring', 'temperatura', 'Temperatura'),
  city:         pega(linha, 'city', 'cidade'),
  state:        pega(linha, 'state', 'estado', 'uf'),
  company_name: pega(linha, 'company_name', 'empresa'),
  bitrix_id:    pega(linha, 'bitrix_id', 'id_bitrix'),
} }));

// Fecha a conta da carga. Roda uma vez, sobre TODOS os itens.
const itens = $input.all();
let criados = 0, falharam = 0;
const erros = [];

for (const it of itens) {
  const r = it.json;
  const status = r.statusCode ?? 0;
  const corpo = r.body ?? {};
  if (status === 200 && corpo.success) criados++;
  else {
    falharam++;
    if (erros.length < 15) erros.push({ status, erro: corpo.error || 'sem detalhe' });
  }
}

return [{ json: {
  total_enviado: itens.length,
  entraram_no_resgate: criados,
  falharam,
  primeiros_erros: erros,
  // Cada um destes é um card NOVO na cadência de resgate. Quem já estava no
  // QS continua lá, intacto, na cadência antiga — os dois convivem.
}}];
